INSERT INTO "questions" ("id", "course_id", "topic", "learning_objective", "section_module", "difficulty", "tags", "question_type", "question_text", "question_description", "answer_options", "correct_answer", "answer_explanation", "explanation_visibility", "points", "partial_credit", "negative_marking", "randomize_options", "requires_manual_review", "status", "version", "parent_question_id", "created_by", "created_at", "updated_at") VALUES ('d1a218bc-5357-4aff-9181-48cafb724d09', '3bd50d2f-7ab3-4193-a6c4-b00f858aca71', 'Compute & Availability', '', '', 'medium', '[]', 'yes_no', 'You plan to deploy several Azure virtual machines. You need to ensure that the services running on the virtual machines are available if a single data center fails. Solution: You deploy the virtual machines to a scale set. Does this meet the goal?', 'Evaluate whether the proposed solution meets the stated Azure availability requirement.', '["Yes","No"]', 'No', 'The solution does not specify that the scale set is configured across multiple data centers, so the proposed solution does not meet the goal.', 'after_submission', 1, 0, 0, 1, 0, 'published', 1, NULL, 'usr_admin_001', '2026-10-28 15:09:02', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "questions" ("id", "course_id", "topic", "learning_objective", "section_module", "difficulty", "tags", "question_type", "question_text", "question_description", "answer_options", "correct_answer", "answer_explanation", "explanation_visibility", "points", "partial_credit", "negative_marking", "randomize_options", "requires_manual_review", "status", "version", "parent_question_id", "created_by", "created_at", "updated_at") VALUES ('be82f2b4-cf3a-47e4-9cba-aa8bdad8efe0', '3bd50d2f-7ab3-4193-a6c4-b00f858aca71', 'Compute & Availability', '', '', 'medium', '[]', 'yes_no', 'You plan to deploy several Azure virtual machines. You need to ensure that the services running on the virtual machines are available if a single data center fails. Solution: You deploy the virtual machines to two or more availability zones. Does this meet the goal?', 'Evaluate whether the proposed solution meets the stated Azure availability requirement.', '["Yes","No"]', 'Yes', 'Availability Zones are physically separate locations within an Azure region. Deploying the virtual machines across two or more availability zones protects the workload from the failure of a single data center.', 'after_submission', 1, 0, 0, 1, 0, 'published', 1, NULL, 'usr_admin_001', '2026-10-28 15:09:02', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "questions" ("id", "course_id", "topic", "learning_objective", "section_module", "difficulty", "tags", "question_type", "question_text", "question_description", "answer_options", "correct_answer", "answer_explanation", "explanation_visibility", "points", "partial_credit", "negative_marking", "randomize_options", "requires_manual_review", "status", "version", "parent_question_id", "created_by", "created_at", "updated_at") VALUES ('27191030-d2c4-46f1-bee8-9960d13f36b8', '3bd50d2f-7ab3-4193-a6c4-b00f858aca71', 'Platform as a Service', '', '', 'easy', '[]', 'yes_no', 'Does a Platform as a Service (PaaS) solution that hosts web apps in Azure provide full control of the operating systems that host the applications?', 'Determine whether the statement about administrative control in the PaaS service model is correct.', '["Yes","No"]', 'No', 'A PaaS solution does not provide direct access to or full control of the operating system hosting the application.', 'after_submission', 1, 0, 0, 1, 0, 'published', 1, NULL, 'usr_admin_001', '2026-10-28 15:09:02', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "questions" ("id", "course_id", "topic", "learning_objective", "section_module", "difficulty", "tags", "question_type", "question_text", "question_description", "answer_options", "correct_answer", "answer_explanation", "explanation_visibility", "points", "partial_credit", "negative_marking", "randomize_options", "requires_manual_review", "status", "version", "parent_question_id", "created_by", "created_at", "updated_at") VALUES ('732b0649-fabb-4a72-8b87-71c69485c3ee', '3bd50d2f-7ab3-4193-a6c4-b00f858aca71', 'Platform as a Service', '', '', 'easy', '[]', 'yes_no', 'Does a Platform as a Service (PaaS) solution that hosts web apps in Azure provide the ability to scale the platform automatically?', 'Determine whether the statement about PaaS autoscaling is correct.', '["Yes","No"]', 'Yes', 'A PaaS solution that hosts web applications can provide automatic scaling capabilities.', 'after_submission', 1, 0, 0, 1, 0, 'published', 1, NULL, 'usr_admin_001', '2026-10-28 15:09:02', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
