INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('968acfc6-88c0-4f6b-8c61-f56322b01c3b', '55827e31-4780-42b0-8f0f-51b110c0aaf0', 1, '{"question_type":"single_choice","question_text":"Your data must be stored in separate geographic locations and must be readable from the secondary location. Which storage redundancy option should you use?","question_description":"Select the Azure Storage redundancy option that provides read access to the secondary region.","answer_options":[{"id":"A","text":"Geo-redundant storage"},{"id":"B","text":"Read-access geo-redundant storage"},{"id":"C","text":"Zone-redundant storage"},{"id":"D","text":"Locally redundant storage"}],"correct_answer":"B","answer_explanation":"Read-access geo-redundant storage provides read-only access to data replicated to the secondary geographic location.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('c88af355-5abc-4d44-9fcc-0bef0c204b8e', '3ecb556c-61fd-442e-bbde-6e6454ba9577', 1, '{"question_type":"single_choice","question_text":"Which cloud service model is used for Azure Virtual Machines?","question_description":"Identify the cloud service model represented by Azure Virtual Machines.","answer_options":[{"id":"A","text":"Software as a Service (SaaS)"},{"id":"B","text":"Platform as a Service (PaaS)"},{"id":"C","text":"Infrastructure as a Service (IaaS)"},{"id":"D","text":"Database as a Service (DaaS)"}],"correct_answer":"C","answer_explanation":"Azure Virtual Machines provide virtualized infrastructure and are an Infrastructure as a Service offering.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('533c1535-4583-49ef-a793-7372aad3e324', '58798e2f-3b97-48b1-979f-ff62e50b1ded', 1, '{"question_type":"single_choice","question_text":"Ten web applications require custom domains, 10 GB of storage, dedicated compute instances, and load balancing. Which App Service tier should be used while minimizing costs?","question_description":"Select the lowest suitable App Service tier that meets all listed requirements.","answer_options":[{"id":"A","text":"Standard"},{"id":"B","text":"Basic"},{"id":"C","text":"Free"},{"id":"D","text":"Shared"}],"correct_answer":"A","answer_explanation":"The Standard tier satisfies the stated storage, dedicated compute, custom domain, and load-balancing requirements.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('f3aac0ea-d800-414d-8987-9054f240039c', 'c71e5baa-bbbe-448e-ac03-63d6e981242b', 1, '{"question_type":"single_choice","question_text":"What expenditure model is normally associated with Azure pay-as-you-go services?","question_description":"Identify the expenditure model associated with consumption-based cloud pricing.","answer_options":[{"id":"A","text":"Capital expenditure"},{"id":"B","text":"Operational expenditure"},{"id":"C","text":"Elastic expenditure"},{"id":"D","text":"Scalable expenditure"}],"correct_answer":"B","answer_explanation":"Pay-as-you-go cloud consumption is an ongoing operating cost and therefore aligns with operational expenditure.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('3fc6b0b7-7772-4bb4-aeeb-68e779f39d57', 'cb0f79fb-47db-4c52-8361-b5319ec4dfb3', 1, '{"question_type":"single_choice","question_text":"Which Azure service is intended for building, testing, and deploying predictive analytics solutions?","question_description":"Choose the Azure service designed for machine-learning workloads.","answer_options":[{"id":"A","text":"Azure Cosmos DB"},{"id":"B","text":"Azure Machine Learning"},{"id":"C","text":"Azure Storage"},{"id":"D","text":"Azure VPN Gateway"}],"correct_answer":"B","answer_explanation":"Azure Machine Learning provides tools for creating, testing, and deploying machine-learning and predictive analytics solutions.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('3c0c6182-9418-44ce-a74f-5469aa9b3d59', '18832666-eac9-48e8-8e34-3b25e3cd34b3', 1, '{"question_type":"single_choice","question_text":"Which technology can automate the creation of identical Azure environments?","question_description":"Select the infrastructure-as-code technology used for repeatable Azure deployments.","answer_options":[{"id":"A","text":"Azure API Management"},{"id":"B","text":"Management groups"},{"id":"C","text":"Azure Resource Manager templates"},{"id":"D","text":"Azure Service Health"}],"correct_answer":"C","answer_explanation":"Azure Resource Manager templates describe Azure infrastructure as code and enable repeatable deployments.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('c45781e3-88ae-4f04-8872-6feb0b1f5c10', 'ebdb0275-fa10-403d-b893-c9cc336bef93', 1, '{"question_type":"single_choice","question_text":"Which virtual machine configuration provides 99.99 percent availability according to the source material?","question_description":"Select the VM deployment configuration that meets the specified availability requirement.","answer_options":[{"id":"A","text":"Two VMs in one availability zone"},{"id":"B","text":"One VM across two availability zones"},{"id":"C","text":"Two VMs across two availability zones"},{"id":"D","text":"One VM in one availability zone"}],"correct_answer":"C","answer_explanation":"The material specifies two or more virtual machine instances distributed across two or more availability zones in the same region.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('a2dff4d2-b874-4042-b0e5-7e448debfb2b', '2d6e82dc-5264-4434-a365-ac2b38c362cb', 1, '{"question_type":"single_choice","question_text":"Developers frequently create and remove customized Windows and Linux virtual machines. Which Azure service helps reduce the administration required?","question_description":"Choose the Azure service designed to simplify provisioning development and test environments.","answer_options":[{"id":"A","text":"Azure Reservations"},{"id":"B","text":"Azure DevTest Labs"},{"id":"C","text":"Microsoft Managed Desktop"},{"id":"D","text":"Azure DNS"}],"correct_answer":"B","answer_explanation":"Azure DevTest Labs supports reusable templates and artifacts for quickly provisioning development and test environments.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('017b8ce2-ccc9-4ca5-afa0-8ebd75ba4ed5', 'd6272e86-5652-4695-95e4-8c4db9f8fd08', 1, '{"question_type":"single_choice","question_text":"Individual remote users require secure access to virtual machines in an Azure virtual network. Which VPN type should be used?","question_description":"Select the VPN configuration appropriate for individual client computers connecting remotely to Azure.","answer_options":[{"id":"A","text":"Site-to-Site VPN"},{"id":"B","text":"VNet-to-VNet VPN"},{"id":"C","text":"Point-to-Site VPN"},{"id":"D","text":"Multi-Site VPN"}],"correct_answer":"C","answer_explanation":"A Point-to-Site VPN creates a secure connection between an individual client computer and an Azure virtual network.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('58259527-e583-4505-8afb-28ea938b9240', '10a88f55-568a-4b6c-8f09-817d9d34185d', 1, '{"question_type":"single_choice","question_text":"Which Azure service should be used to protect administrative credentials during automated deployments?","question_description":"Select the Azure service designed for securely storing secrets and credentials.","answer_options":[{"id":"A","text":"Azure Information Protection"},{"id":"B","text":"Azure Key Vault"},{"id":"C","text":"Azure Multi-Factor Authentication"},{"id":"D","text":"Azure Advisor"}],"correct_answer":"B","answer_explanation":"Azure Key Vault is designed to securely store secrets such as passwords, credentials, keys, and certificates.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('672815e0-074a-4423-83b5-7f7fcafd87e1', '3cb62ee3-9402-42cd-8b18-544e11d8de0e', 1, '{"question_type":"single_choice","question_text":"Which service can detect risky sign-ins such as anonymous IP address usage?","question_description":"Identify the identity security service used to detect sign-in risks.","answer_options":[{"id":"A","text":"Privileged Identity Management"},{"id":"B","text":"Microsoft Entra ID Identity Protection"},{"id":"C","text":"Azure DevTest Labs"},{"id":"D","text":"Azure Advisor"}],"correct_answer":"B","answer_explanation":"Microsoft Entra ID Identity Protection identifies risks including anonymous IP addresses and unfamiliar sign-in properties.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('1212b8da-f456-455b-aefe-9c258547f480', '5455417a-902b-44b8-9f96-e9abffc99149', 1, '{"question_type":"single_choice","question_text":"Which Azure resource can allow or deny inbound and outbound network traffic according to source, destination, port, and protocol?","question_description":"Select the Azure networking resource that provides rule-based traffic filtering.","answer_options":[{"id":"A","text":"Network security group"},{"id":"B","text":"Resource group"},{"id":"C","text":"Azure Key Vault"},{"id":"D","text":"Azure Policy"}],"correct_answer":"A","answer_explanation":"A network security group contains rules that filter inbound and outbound network traffic.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('47c3701b-b488-4e71-856d-c696dca6ca7a', '50aba22b-6ac3-4388-be2a-cd932499db74', 1, '{"question_type":"single_choice","question_text":"Which cloud-computing concept describes the ability of a service to continue operating when a component fails?","question_description":"Identify the cloud concept associated with continued operation after component failure.","answer_options":[{"id":"A","text":"Scalability"},{"id":"B","text":"Elasticity"},{"id":"C","text":"Fault tolerance"},{"id":"D","text":"Low latency"}],"correct_answer":"C","answer_explanation":"Fault tolerance enables a service to continue functioning despite failure of one or more components.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('7f07cbe5-1129-4900-b69e-e16e19f574e5', '769dd0f2-7a84-47a4-9673-be2f718138bd', 1, '{"question_type":"single_choice","question_text":"Which option is a characteristic of a public cloud?","question_description":"Select the characteristic commonly associated with public cloud services.","answer_options":[{"id":"A","text":"Dedicated customer hardware"},{"id":"B","text":"Unsecured connections"},{"id":"C","text":"Limited storage"},{"id":"D","text":"Metered pricing"}],"correct_answer":"D","answer_explanation":"Public cloud services commonly provide metered or pay-as-you-go pricing in which customers pay for resources they consume.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('67956f17-63ff-4a1c-b46f-e1d6aff46e0e', '53355718-c61d-4007-802b-a43a6afa81ae', 1, '{"question_type":"single_choice","question_text":"Which combination consists of Platform as a Service solutions?","question_description":"Identify the pair in which both Azure services use the PaaS service model.","answer_options":[{"id":"A","text":"Azure Virtual Machines and SQL Server on VMs"},{"id":"B","text":"Azure App Service and Azure SQL Database"},{"id":"C","text":"Azure Virtual Machines and Azure App Service"},{"id":"D","text":"Physical servers and Azure SQL Database"}],"correct_answer":"B","answer_explanation":"Azure App Service and Azure SQL Database are examples of managed Platform as a Service offerings.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('c2dd5906-afbb-4bc1-80e0-bf9d6f26ceb7', 'e5945aa2-d5c1-4b56-b8ba-c18a1ee9066a', 1, '{"question_type":"single_choice","question_text":"A workload has low demand for most of each month and very high demand during one week. Which cloud benefit allows resources to adjust to this demand?","question_description":"Identify the cloud characteristic that dynamically adjusts resources according to workload demand.","answer_options":[{"id":"A","text":"High availability"},{"id":"B","text":"Elasticity"},{"id":"C","text":"Low latency"},{"id":"D","text":"Fault tolerance"}],"correct_answer":"B","answer_explanation":"Elasticity allows compute resources to increase when demand rises and decrease when those resources are no longer required.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('28d6b12e-7253-444c-a345-e92ee05b5801', 'c5dc8f11-8104-49f9-91e0-768e836c8723', 1, '{"question_type":"single_choice","question_text":"Which service model generally minimizes administrative effort when hosting a custom web application?","question_description":"Select the service model where the provider manages much of the underlying infrastructure.","answer_options":[{"id":"A","text":"Software as a Service (SaaS)"},{"id":"B","text":"Platform as a Service (PaaS)"},{"id":"C","text":"Infrastructure as a Service (IaaS)"},{"id":"D","text":"Private cloud"}],"correct_answer":"B","answer_explanation":"PaaS lets the provider manage much of the underlying infrastructure while the customer focuses on the application.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('6c8f9784-ffd0-44ea-8506-f011a22c9644', '19074f9e-916b-4cbe-85f5-3df5546302f9', 1, '{"question_type":"single_choice","question_text":"An organization wants to keep its existing on-premises servers but expand capacity using Azure. Which cloud model is appropriate?","question_description":"Identify the cloud model that combines on-premises infrastructure with public cloud resources.","answer_options":[{"id":"A","text":"Public cloud only"},{"id":"B","text":"Private cloud only"},{"id":"C","text":"Hybrid cloud"},{"id":"D","text":"Software as a Service"}],"correct_answer":"C","answer_explanation":"Hybrid cloud combines on-premises or private infrastructure with public-cloud resources.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('fb121ad1-892f-464f-91f6-c829345703e0', 'dcc94114-1af8-46db-9bc1-47c2249208fe', 1, '{"question_type":"single_choice","question_text":"In which cloud model is the underlying hardware owned by a third party and shared among multiple customers?","question_description":"Choose the cloud deployment model described.","answer_options":[{"id":"A","text":"Private cloud"},{"id":"B","text":"Hybrid cloud"},{"id":"C","text":"Public cloud"},{"id":"D","text":"On-premises"}],"correct_answer":"C","answer_explanation":"In a public cloud, the cloud provider owns and operates the underlying infrastructure used to provide services to multiple customers.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('9997e061-f185-47cc-937f-e2c7cfcb13c5', '96aaf4bf-3213-4a00-af97-5cfde8fc368f', 1, '{"question_type":"single_choice","question_text":"Which Azure resource is an example of Infrastructure as a Service?","question_description":"Select the Azure service representing virtualized infrastructure.","answer_options":[{"id":"A","text":"Azure Web App"},{"id":"B","text":"Azure Virtual Machine"},{"id":"C","text":"Azure Logic Apps"},{"id":"D","text":"Azure SQL Database"}],"correct_answer":"B","answer_explanation":"An Azure Virtual Machine provides virtualized compute infrastructure and is therefore an Infrastructure as a Service resource.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('a6c6f6e5-f4b3-44f5-944e-31d350e91a1d', '8c6505ef-1d00-40fb-a4b6-293978dacb34', 1, '{"question_type":"single_choice","question_text":"You have 50 virtual machines on-premises and 50 virtual machines in Azure, and the environments communicate. What cloud model is this?","question_description":"Identify the cloud deployment model that combines on-premises and Azure resources.","answer_options":[{"id":"A","text":"Hybrid cloud"},{"id":"B","text":"Private cloud"},{"id":"C","text":"Public cloud"},{"id":"D","text":"Software as a Service"}],"correct_answer":"A","answer_explanation":"Hybrid cloud combines an organization''s on-premises infrastructure with public-cloud infrastructure.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('d971baa1-8e7d-4a18-9025-0b9b250b152b', 'fcee988e-af87-4eff-9dba-047fe527444a', 1, '{"question_type":"single_choice","question_text":"Which action represents vertical scaling?","question_description":"Identify an example of scaling up an existing resource.","answer_options":[{"id":"A","text":"Adding more virtual machines"},{"id":"B","text":"Adding CPU or memory to an existing virtual machine"},{"id":"C","text":"Deploying to a second Azure region"},{"id":"D","text":"Creating another virtual network"}],"correct_answer":"B","answer_explanation":"Vertical scaling changes the capacity of an existing resource rather than adding additional instances.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('f408b6aa-0d54-44c0-8aee-f96216631811', 'f80b2216-259e-4193-be1e-52c1503884d3', 1, '{"question_type":"single_choice","question_text":"Which is a feature of an Azure virtual network?","question_description":"Select a core capability provided by Azure Virtual Network.","answer_options":[{"id":"A","text":"Cost analysis"},{"id":"B","text":"Packet inspection by default"},{"id":"C","text":"Geo-redundancy"},{"id":"D","text":"Isolation and segmentation"}],"correct_answer":"D","answer_explanation":"Virtual networks provide isolated networking and can be segmented into subnets.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('4d8c6bdc-4206-438e-a971-74db10142c9e', '66b41799-7454-49db-86a5-44f99dca8302', 1, '{"question_type":"single_choice","question_text":"Which cloud benefit focuses on continuous application accessibility with minimal downtime?","question_description":"Identify the cloud concept concerned with keeping applications accessible.","answer_options":[{"id":"A","text":"Agility"},{"id":"B","text":"Scalability"},{"id":"C","text":"Elasticity"},{"id":"D","text":"High availability"}],"correct_answer":"D","answer_explanation":"High availability focuses on keeping an application or service accessible despite failures.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('20887841-bcf9-4c3a-a5e7-f9f091c697d6', '538680b3-3563-4dda-9e86-82c42a4b7f09', 1, '{"question_type":"single_choice","question_text":"What type of failure can Azure Availability Zones protect against?","question_description":"Identify the infrastructure failure addressed by distributing resources across Availability Zones.","answer_options":[{"id":"A","text":"Only a disk failure"},{"id":"B","text":"An entire Azure region failure"},{"id":"C","text":"An Azure datacenter failure"},{"id":"D","text":"A password failure"}],"correct_answer":"C","answer_explanation":"Availability Zones are physically separate locations within a region, providing protection against individual datacenter failures.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('83e9a770-d145-4725-bff1-165698739d68', 'a4b6383a-727e-4476-a9f8-5028c7d76fbe', 1, '{"question_type":"single_choice","question_text":"Which Azure resource represents an on-premises VPN device?","question_description":"Select the Azure resource used to represent the on-premises side of a VPN connection.","answer_options":[{"id":"A","text":"Application Gateway"},{"id":"B","text":"Local network gateway"},{"id":"C","text":"Load Balancer"},{"id":"D","text":"Network security group"}],"correct_answer":"B","answer_explanation":"A local network gateway represents the on-premises VPN device and network information in Azure.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('3b28d816-29ad-4457-b8a8-4655b8536632', '574c55c2-3080-4f1d-8afc-d41f8575fe7c', 1, '{"question_type":"single_choice","question_text":"You reach an Azure subscription quota and need it increased. What should you do?","question_description":"Select the appropriate method for requesting an Azure quota increase.","answer_options":[{"id":"A","text":"Create a Service Health alert"},{"id":"B","text":"Upgrade the support plan"},{"id":"C","text":"Modify Azure Policy"},{"id":"D","text":"Create a support request"}],"correct_answer":"D","answer_explanation":"The source instructs users to request quota increases through an Azure support request.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('97d8f00b-3853-43f8-8ae9-00fe9b02b7cd', '7036c292-28e0-4a34-8fb6-5cbe245ac367', 1, '{"question_type":"single_choice","question_text":"A server must be placed on a separate network segment from other servers. Which solution should you use?","question_description":"Choose the solution that provides network-level separation.","answer_options":[{"id":"A","text":"Separate resource groups"},{"id":"B","text":"Separate virtual networks"},{"id":"C","text":"Separate tags"},{"id":"D","text":"Separate subscriptions only"}],"correct_answer":"B","answer_explanation":"Placing the server in a different virtual network provides network-level separation from the other servers.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('cda5659a-2cea-4967-8a5d-709d7c430c4f', '6c1f1330-346f-46ad-ae98-cb8c5967868f', 1, '{"question_type":"single_choice","question_text":"Which service should be used to create a cloud file share that Windows computers can map as a network drive?","question_description":"Select the Azure Storage service designed to provide managed file shares.","answer_options":[{"id":"A","text":"Azure SQL Database"},{"id":"B","text":"Virtual machine data disk"},{"id":"C","text":"Azure Files"},{"id":"D","text":"Azure Blob Storage"}],"correct_answer":"C","answer_explanation":"Azure Files provides managed file shares that Windows clients can mount and access as network file shares.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('d76eb7f1-af0b-4d75-8d53-34026ba42fd8', 'a48b29c3-8ddb-4df5-ac91-f5fa588ef903', 1, '{"question_type":"single_choice","question_text":"Which database is suited to storing JSON documents and supporting globally distributed data?","question_description":"Select the Azure database service designed for globally distributed modern application data.","answer_options":[{"id":"A","text":"Azure SQL Database"},{"id":"B","text":"Azure Cosmos DB"},{"id":"C","text":"Azure Files"},{"id":"D","text":"Azure Queue Storage"}],"correct_answer":"B","answer_explanation":"Azure Cosmos DB is a globally distributed database service suited to JSON and other modern application data.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('ac3060a5-7eef-4a1b-a746-259ddcb1a5b9', '3176d5e4-67ca-415f-94d9-9c829091f6d7', 1, '{"question_type":"single_choice","question_text":"What should an organization create before deploying and consuming Azure resources?","question_description":"Identify the Azure construct within which resources are consumed and billed.","answer_options":[{"id":"A","text":"Subscription"},{"id":"B","text":"Resource group"},{"id":"C","text":"Virtual network"},{"id":"D","text":"Management group"}],"correct_answer":"A","answer_explanation":"Azure resources are deployed and billed within subscriptions.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('36e1246a-d56f-4050-a985-724c5c056ce9', 'ff10569b-2d75-4db8-b7b8-54b1ee5e6216', 1, '{"question_type":"single_choice","question_text":"What does an Azure Service Level Agreement for virtual machines primarily guarantee?","question_description":"Identify the primary metric used for Azure VM availability commitments.","answer_options":[{"id":"A","text":"Uptime"},{"id":"B","text":"Feature availability"},{"id":"C","text":"Unlimited bandwidth"},{"id":"D","text":"Application performance"}],"correct_answer":"A","answer_explanation":"Virtual machine SLAs define availability or connectivity commitments expressed as uptime percentages.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('06707fbc-4a8f-4011-96de-67650e51af51', '9a052f63-3c47-4da7-8e7d-c2d33e633d1f', 1, '{"question_type":"single_choice","question_text":"Which Azure service provides information about planned Azure maintenance that might affect your resources?","question_description":"Select the Azure service used to review personalized service health information.","answer_options":[{"id":"A","text":"Azure Monitor"},{"id":"B","text":"Azure Service Health"},{"id":"C","text":"Azure Advisor"},{"id":"D","text":"Azure Key Vault"}],"correct_answer":"B","answer_explanation":"Azure Service Health provides personalized information about outages, planned maintenance, and health advisories.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('213a326c-f337-471b-a25a-abe936255703', 'ae37ab6b-bc93-497c-b923-60ef77c804ac', 1, '{"question_type":"single_choice","question_text":"Which Azure service provides bidirectional communication between IoT devices and Azure?","question_description":"Identify the Azure service designed as a messaging hub for IoT devices.","answer_options":[{"id":"A","text":"Azure IoT Hub"},{"id":"B","text":"Azure Functions"},{"id":"C","text":"Azure SQL Database"},{"id":"D","text":"Azure DevOps"}],"correct_answer":"A","answer_explanation":"Azure IoT Hub acts as a central messaging hub between IoT devices and cloud applications.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('7b1a112d-7f43-4279-a3d8-858a0efb85ac', '66ec1a9f-2e41-4b42-a7af-f560a7b5cb57', 1, '{"question_type":"single_choice","question_text":"Which tool estimates potential cost differences when moving workloads from on-premises infrastructure to Azure?","question_description":"Select the Microsoft tool designed to compare on-premises and Azure infrastructure costs.","answer_options":[{"id":"A","text":"Azure Advisor"},{"id":"B","text":"Total Cost of Ownership Calculator"},{"id":"C","text":"Azure Monitor"},{"id":"D","text":"Azure Service Health"}],"correct_answer":"B","answer_explanation":"The Total Cost of Ownership Calculator compares anticipated on-premises infrastructure costs with equivalent Azure workloads.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('aa78cbd5-9ced-4906-8728-2727d835a8ce', 'd5896433-324e-4c01-a8fd-c5cf09545fbe', 1, '{"question_type":"single_choice","question_text":"Where should you obtain a third-party virtual security appliance for Azure?","question_description":"Select the service that provides Microsoft and partner solutions for deployment to Azure.","answer_options":[{"id":"A","text":"Azure Subscriptions"},{"id":"B","text":"Microsoft Defender for Cloud"},{"id":"C","text":"Azure Marketplace"},{"id":"D","text":"Microsoft Store"}],"correct_answer":"C","answer_explanation":"Azure Marketplace provides Microsoft and partner solutions that can be deployed to Azure.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('5397517a-5caf-4f24-9b5b-fc774e7e4b8d', '4a3c9c54-7fab-414d-a462-9e06bee01b8d', 1, '{"question_type":"single_choice","question_text":"Which Azure service provides serverless execution of event-triggered code?","question_description":"Identify the Azure compute service designed to execute event-driven code without managing servers.","answer_options":[{"id":"A","text":"Azure Virtual Machines"},{"id":"B","text":"Azure Functions"},{"id":"C","text":"Azure Storage"},{"id":"D","text":"Azure Dedicated Hosts"}],"correct_answer":"B","answer_explanation":"Azure Functions executes event-driven code without requiring the customer to explicitly provision or manage servers.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('85c6f6cb-a98e-4f01-9008-a124f1f63543', '0fa3fae7-f0fb-4d69-8c5d-c618b41eacfb', 1, '{"question_type":"single_choice","question_text":"Which Azure technology is appropriate for repeatable deployments of identical Azure resources?","question_description":"Select the infrastructure-as-code option used for repeatable Azure deployments.","answer_options":[{"id":"A","text":"Azure Resource Manager templates"},{"id":"B","text":"Azure Advisor"},{"id":"C","text":"Azure Service Health"},{"id":"D","text":"Azure Network Watcher"}],"correct_answer":"A","answer_explanation":"Azure Resource Manager templates define infrastructure declaratively and can be reused for repeatable resource deployments.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('8fb12929-42e7-4df0-8cf0-d5978da9264a', 'ad48776b-e933-4730-ad88-9b1cf10fc8ec', 1, '{"question_type":"single_choice","question_text":"Which Azure service can identify underutilized or unused virtual machines?","question_description":"Select the Azure service that analyzes resources and provides optimization recommendations.","answer_options":[{"id":"A","text":"Azure Advisor"},{"id":"B","text":"Azure Reservations"},{"id":"C","text":"Azure Policy"},{"id":"D","text":"Azure DNS"}],"correct_answer":"A","answer_explanation":"Azure Advisor analyzes resource utilization and can provide recommendations concerning idle and underutilized resources.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('38648b29-2e03-427f-a16c-1ec48c46ffb9', '063fb2cc-ed61-405a-b142-83596e31a0c3', 1, '{"question_type":"single_choice","question_text":"What should you use in the Azure portal to grant a user the Reader role on a resource group?","question_description":"Select the Azure portal feature used to assign Azure RBAC roles.","answer_options":[{"id":"A","text":"Access control (IAM)"},{"id":"B","text":"Azure Service Health"},{"id":"C","text":"Azure Monitor"},{"id":"D","text":"Azure DNS"}],"correct_answer":"A","answer_explanation":"Access control (IAM) is used to manage Azure role-based access control role assignments at scopes such as resource groups.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('9ba39a7e-d957-493d-b5d1-15272490f8d5', 'bb18c821-2610-4c86-b19c-28cb168158fc', 1, '{"question_type":"single_choice","question_text":"Which Azure service provides version-control capabilities?","question_description":"Select the Azure DevOps service used for source-code version control.","answer_options":[{"id":"A","text":"Azure Repos"},{"id":"B","text":"Azure DevTest Labs"},{"id":"C","text":"Azure Storage"},{"id":"D","text":"Azure Cosmos DB"}],"correct_answer":"A","answer_explanation":"Azure Repos provides version-control tools and supports source-code management.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('ccce99f4-ea0b-411b-aa14-7380e4e374fb', '37b75a70-e7b3-4e0b-8775-96e9dc080fce', 1, '{"question_type":"single_choice","question_text":"An application must automatically send email notifications based on rules. Which serverless solution is appropriate?","question_description":"Select the Azure service designed for automated event-driven workflows.","answer_options":[{"id":"A","text":"Azure Web App"},{"id":"B","text":"Azure Marketplace VM image"},{"id":"C","text":"Azure Logic Apps"},{"id":"D","text":"Azure API App"}],"correct_answer":"C","answer_explanation":"Azure Logic Apps can create automated workflows and perform actions such as sending notifications when events occur.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('c875e914-52e9-497c-afa5-900baf83c933', 'e20ffe57-7cc3-4dc9-ba51-533ab6aaa3c6', 1, '{"question_type":"single_choice","question_text":"A website serves large videos to users around the world. Which Azure technology can improve the playback experience?","question_description":"Select the technology that can deliver cached content from locations closer to users.","answer_options":[{"id":"A","text":"Application Gateway"},{"id":"B","text":"ExpressRoute"},{"id":"C","text":"Content Delivery Network"},{"id":"D","text":"Traffic Manager"}],"correct_answer":"C","answer_explanation":"A Content Delivery Network caches content at distributed edge locations closer to users, reducing latency.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('70a7f477-de45-42de-a54b-f8200ad06e6e', '8e3387cb-9150-499d-a7bb-8fd81afa4108', 1, '{"question_type":"single_choice","question_text":"Which Azure service lets you visually build machine-learning models?","question_description":"Select the machine-learning capability that provides a visual design canvas.","answer_options":[{"id":"A","text":"Azure Logic Apps"},{"id":"B","text":"Azure Machine Learning Designer"},{"id":"C","text":"Azure Batch"},{"id":"D","text":"Azure Cosmos DB"}],"correct_answer":"B","answer_explanation":"Azure Machine Learning Designer provides a visual canvas for connecting datasets and modules to build machine-learning models.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('708bb1cc-9e67-4722-91d5-60c8be84a123', 'ebfe9e03-c953-43fb-885b-8eafa5d5a1e5', 1, '{"question_type":"single_choice","question_text":"Which Azure service can automatically alert you when an administrator stops an Azure virtual machine?","question_description":"Select the Azure monitoring service that can generate alerts based on defined conditions and activities.","answer_options":[{"id":"A","text":"Azure Advisor"},{"id":"B","text":"Azure Service Health"},{"id":"C","text":"Azure Monitor"},{"id":"D","text":"Azure Network Watcher"}],"correct_answer":"C","answer_explanation":"Azure Monitor can monitor activity and generate alerts based on defined conditions.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('b85f7a20-e274-496c-9f50-ac6e995c24a9', '4d0c7628-fcd4-4709-b33a-93389b65ef42', 1, '{"question_type":"single_choice","question_text":"Which Azure service can centrally filter network traffic across multiple virtual networks and subscriptions?","question_description":"Select the managed Azure network security service designed for centralized traffic filtering.","answer_options":[{"id":"A","text":"Azure Firewall"},{"id":"B","text":"Application security group"},{"id":"C","text":"Azure DDoS Protection"},{"id":"D","text":"Network security group"}],"correct_answer":"A","answer_explanation":"Azure Firewall provides centralized network and application connectivity policy enforcement across Azure networks.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('9b6ff879-6199-4008-a7e3-8599628f1eca', 'd9fca774-6b36-44bf-be1f-81c8f5492004', 1, '{"question_type":"single_choice","question_text":"Which Azure service can securely store certificates, passwords, keys, and other secrets?","question_description":"Select the Azure service designed for centralized secure storage of secrets.","answer_options":[{"id":"A","text":"Azure Storage"},{"id":"B","text":"Azure Monitor"},{"id":"C","text":"Azure Key Vault"},{"id":"D","text":"Azure Advisor"}],"correct_answer":"C","answer_explanation":"Azure Key Vault provides secure storage and controlled access for secrets, cryptographic keys, and certificates.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('516a215e-214c-4f24-9532-57c2942e8a5e', 'e7db5ba0-2284-468d-ab05-ab114dc2d57b', 1, '{"question_type":"single_choice","question_text":"Which Microsoft security service provides Security Information and Event Management capabilities?","question_description":"Select Microsoft''s cloud-native SIEM solution.","answer_options":[{"id":"A","text":"Azure Analysis Services"},{"id":"B","text":"Microsoft Sentinel"},{"id":"C","text":"Azure Information Protection"},{"id":"D","text":"Azure Cognitive Services"}],"correct_answer":"B","answer_explanation":"Microsoft Sentinel provides cloud-native Security Information and Event Management capabilities.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('c7fd29e8-44ee-403f-8c24-99ea318325c7', '321a7fee-1cff-4699-acf7-89ea057965e9', 1, '{"question_type":"single_choice","question_text":"Which Azure service should you use to review your secure score?","question_description":"Select the security management service that assesses Azure security posture.","answer_options":[{"id":"A","text":"Azure Monitor"},{"id":"B","text":"Azure Advisor"},{"id":"C","text":"Help and Support"},{"id":"D","text":"Microsoft Defender for Cloud"}],"correct_answer":"D","answer_explanation":"Microsoft Defender for Cloud continually assesses security posture and provides Secure Score.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('e8e5cc1e-f33b-4a9d-8e96-2d599a12435d', '8313e974-52f5-44b0-a469-b2a349f8f927', 1, '{"question_type":"single_choice","question_text":"You need to prevent virtual machines from being created in a resource group while still allowing other resource types. What should you use?","question_description":"Select the Azure governance capability that can deny deployment of a specific resource type at a defined scope.","answer_options":[{"id":"A","text":"Resource lock"},{"id":"B","text":"Azure role"},{"id":"C","text":"Tag"},{"id":"D","text":"Azure Policy"}],"correct_answer":"D","answer_explanation":"Azure Policy can enforce rules concerning which resource types are permitted or denied at a particular scope.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 12:51:37') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('f6913c47-3b0f-4286-8d9d-174ac0edd83b', 'd1a218bc-5357-4aff-9181-48cafb724d09', 1, '{"question_type":"yes_no","question_text":"You plan to deploy several Azure virtual machines. You need to ensure that the services running on the virtual machines are available if a single data center fails. Solution: You deploy the virtual machines to a scale set. Does this meet the goal?","question_description":"Evaluate whether the proposed solution meets the stated Azure availability requirement.","answer_options":["Yes","No"],"correct_answer":"No","answer_explanation":"The solution does not specify that the scale set is configured across multiple data centers, so the proposed solution does not meet the goal.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('3bb67de0-f110-4d80-98bb-44f3249ae70a', 'be82f2b4-cf3a-47e4-9cba-aa8bdad8efe0', 1, '{"question_type":"yes_no","question_text":"You plan to deploy several Azure virtual machines. You need to ensure that the services running on the virtual machines are available if a single data center fails. Solution: You deploy the virtual machines to two or more availability zones. Does this meet the goal?","question_description":"Evaluate whether the proposed solution meets the stated Azure availability requirement.","answer_options":["Yes","No"],"correct_answer":"Yes","answer_explanation":"Availability Zones are physically separate locations within an Azure region. Deploying the virtual machines across two or more availability zones protects the workload from the failure of a single data center.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('01859ffe-aba0-42f5-ab9b-50a6796161f0', '27191030-d2c4-46f1-bee8-9960d13f36b8', 1, '{"question_type":"yes_no","question_text":"Does a Platform as a Service (PaaS) solution that hosts web apps in Azure provide full control of the operating systems that host the applications?","question_description":"Determine whether the statement about administrative control in the PaaS service model is correct.","answer_options":["Yes","No"],"correct_answer":"No","answer_explanation":"A PaaS solution does not provide direct access to or full control of the operating system hosting the application.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('7a7033a1-a052-4e86-b12f-d05a689531e5', '732b0649-fabb-4a72-8b87-71c69485c3ee', 1, '{"question_type":"yes_no","question_text":"Does a Platform as a Service (PaaS) solution that hosts web apps in Azure provide the ability to scale the platform automatically?","question_description":"Determine whether the statement about PaaS autoscaling is correct.","answer_options":["Yes","No"],"correct_answer":"Yes","answer_explanation":"A PaaS solution that hosts web applications can provide automatic scaling capabilities.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('1b3b362a-208f-4487-9b4f-c37dd6a635d6', 'bebd0ee9-95ec-420f-a8f5-b709cfd97903', 1, '{"question_type":"yes_no","question_text":"Does a Platform as a Service (PaaS) solution provide a framework that developers can use to develop or customize cloud-based applications?","question_description":"Determine whether the statement about the development capabilities of PaaS is correct.","answer_options":["Yes","No"],"correct_answer":"Yes","answer_explanation":"PaaS provides a framework and development capabilities that developers can use to build and customize cloud-based applications.","points":1,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 15:09:02') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('2bd3a718-d346-4d3d-a235-3139d2c2d876', '3f984911-4161-4f8a-a7e2-053dc752a798', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"To achieve a hybrid cloud model, a company must always migrate from a private cloud model.","options":["Yes","No"]},{"id":"stmt_2","statement":"A company can extend the capacity of its internal network by using the public cloud.","options":["Yes","No"]},{"id":"stmt_3","statement":"In a public cloud model, only guest users at your company can access the resources in the cloud.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"Yes","stmt_3":"No"},"answer_explanation":"Statement 1: A company can adopt a hybrid cloud model directly without migrating from an existing private cloud. Statement 2: Public cloud can extend on-premises network and compute capacity. Statement 3: In a public cloud model, authorized corporate users, administrators, and services can access resources, not just guest users.","points":3,"tags":["Hotspot","CloudModels","HybridCloud","PublicCloud"]}', 'Initial version', 'usr_admin_001', '2026-10-28 19:05:34') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('416c3d7b-6223-42e8-9ffa-20047d39ed78', '1881b9e2-2206-4b40-bd77-9252cb21197c', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"To achieve a hybrid cloud model, a company must always migrate from a private cloud model.","options":["Yes","No"]},{"id":"stmt_2","statement":"A company can extend the capacity of its internal network by using the public cloud.","options":["Yes","No"]},{"id":"stmt_3","statement":"In a public cloud model, only guest users at your company can access the resources in the cloud.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"Yes","stmt_3":"No"},"answer_explanation":"Box 1: No - It is not true that a company must always migrate from a private cloud model to implement a hybrid cloud. You could start with a public cloud and then combine that with an on-premises infrastructure to implement a hybrid cloud.\n\nBox 2: Yes - A company can extend the capacity of its internal network by using the public cloud. This is very common. When you need more capacity, rather than pay for new on-premises infrastructure, you can configure a cloud environment and connect your on-premises network to the cloud environment by using a VPN.\n\nBox 3: No - It is not true that only guest users can access cloud resources. You can give anyone with an account in Azure Active Directory access to the cloud resources. There are many authentication scenarios, but a common one is to replicate your on-premises Active Directory accounts to Azure Active Directory and provide access to the Azure Active Directory accounts. Another commonly used authentication method is Federation, where authentication for access to cloud resources is passed to another authentication provider such as an on-premises Active Directory.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:08:18') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('5621bcaf-ab7f-4847-a905-d6ca17e07214', 'da65b479-44ed-489c-ac86-e3f3cd0191a5', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"Azure Pay-As-You-Go pricing is an example of CapEx.","options":["Yes","No"]},{"id":"stmt_2","statement":"Paying electricity for your datacenter is an example of OpEx.","options":["Yes","No"]},{"id":"stmt_3","statement":"Deploying your own datacenter is an example of CapEx.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"No","stmt_3":"Yes"},"answer_explanation":"Box 1: No - With the pay-as-you-go model, you pay for services as you use them. This is OpEx (Operational Expenditure), not CapEx (Capital Expenditure). CapEx is where you pay for something upfront, for example, buying a new physical server.\n\nBox 2: No - Paying for electricity for your own datacenter is classed as CapEx, not OpEx, according to the provided source explanation.\n\nBox 3: Yes - Deploying your own datacenter is an example of CapEx. This is because you need to purchase all the infrastructure upfront before you can use it.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:10:19') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('0dad7ce7-bb2e-432b-b96e-f8e2ffba864d', 'e28891e6-30f9-4ebe-bf0a-2c2dca33a5bd', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"With software as a service (SaaS), you must apply software updates.","options":["Yes","No"]},{"id":"stmt_2","statement":"With infrastructure as a service (IaaS), you must install the software that you want to use.","options":["Yes","No"]},{"id":"stmt_3","statement":"Azure Backup is an example of platform as a service (PaaS).","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"Yes","stmt_3":"Yes"},"answer_explanation":"Statement 1: With software as a service (SaaS), you must apply software updates. Answer: No. Explanation: In a SaaS model, such as Microsoft 365, Salesforce, or Gmail, the cloud provider manages the entire application stack. This includes hardware, virtualization, operating systems, and the application software itself. The vendor automatically handles all software updates, feature upgrades, and bug patches behind the scenes without any effort or intervention from the end user.\n\nStatement 2: With infrastructure as a service (IaaS), you must install the software that you want to use. Answer: Yes. Explanation: IaaS provides the rawest form of cloud computing resources, typically virtual machines, storage, and networking. While the cloud provider manages the physical data center hardware and hypervisor, you are given full administrative control over the operating system. This means you are completely responsible for installing, configuring, and maintaining any software, runtimes, middleware, or applications you intend to run.\n\nStatement 3: Azure Backup is an example of platform as a service (PaaS). Answer: Yes. Explanation: PaaS provides a managed environment where you can deploy applications or consume services.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:14:36') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('e50c4237-8af7-4768-82df-a7221d835541', 'a29c07b9-2b88-4164-bfb1-0954ae5694d0', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"Microsoft SQL Server 2019 installed on an Azure virtual machine is an example of platform as a service (PaaS).","options":["Yes","No"]},{"id":"stmt_2","statement":"Azure SQL Database is an example of platform as a service (PaaS).","options":["Yes","No"]},{"id":"stmt_3","statement":"Azure Cosmos DB is an example of software as a service (SaaS).","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"Yes","stmt_3":"No"},"answer_explanation":"Statement 1: Microsoft SQL Server 2019 installed on an Azure virtual machine is an example of platform as a service (PaaS). Answer: No. Explanation: When you deploy an Azure Virtual Machine and install SQL Server on it, you are leveraging Infrastructure as a Service (IaaS). You are responsible for managing the underlying operating system, configuring the SQL Server installation, managing storage disks, and applying both OS patches and database cumulative updates.\n\nStatement 2: Azure SQL Database is an example of platform as a service (PaaS). Answer: Yes. Explanation: Azure SQL Database is a fully managed relational database engine. Azure handles all core infrastructure management, including hardware provisioning, operating system patching, database software updates, backups, and high availability configurations. You only manage your schema, data, and access permissions, which fits the definition of PaaS.\n\nStatement 3: Azure Cosmos DB is an example of software as a service (SaaS). Answer: No. Explanation: Azure Cosmos DB is not classified as SaaS in this question.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:15:45') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('1396465c-ff60-49f0-8ba2-b212e447398b', '4cb4074c-e1eb-47d1-97f6-e34976256841', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"Azure Files is an example of infrastructure as a service (IaaS).","options":["Yes","No"]},{"id":"stmt_2","statement":"A DNS server that runs on an Azure virtual machine is an example of platform as a service (PaaS).","options":["Yes","No"]},{"id":"stmt_3","statement":"Microsoft Intune is an example of software as a service (SaaS).","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"No","stmt_3":"Yes"},"answer_explanation":"Statement 1: Azure Files is an example of infrastructure as a service (IaaS). Answer: No. Explanation: Azure Files is actually a managed file storage service, which is considered a part of Platform as a Service (PaaS).\n\nStatement 2: A DNS server that runs on an Azure virtual machine is an example of platform as a service (PaaS). Answer: No. Explanation: A DNS server running on an Azure virtual machine would be considered Infrastructure as a Service (IaaS) because it involves managing the underlying infrastructure.\n\nStatement 3: Microsoft Intune is an example of software as a service (SaaS). Answer: Yes. Explanation: Microsoft Intune is indeed a Software as a Service (SaaS) as it provides software over the internet without needing local installation.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:16:36') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('4fc24e89-d483-4a4e-8d56-da4f2514ba17', 'f77f72b0-813b-4b04-b808-b15b3e57edec', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"Cloud computing provides elastic scalability.","options":["Yes","No"]},{"id":"stmt_2","statement":"Customers can minimize capital expenditure (CapEx) by using a public cloud.","options":["Yes","No"]},{"id":"stmt_3","statement":"Cloud computing leverages virtualization to provide services to multiple customers simultaneously.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"Yes","stmt_2":"Yes","stmt_3":"Yes"},"answer_explanation":"Statement 1: Yes - Cloud computing provides elastic scalability. Elasticity means the system can automatically add or remove resources, such as server power or storage, to match current demand.\n\nStatement 2: Yes - Customers can minimize capital expenditure (CapEx) by using a public cloud. Instead of buying expensive hardware upfront, customers pay for what they use as an ongoing operating expense (OpEx).\n\nStatement 3: Yes - Cloud computing leverages virtualization to provide services to multiple customers simultaneously. Virtualization allows a single physical server to be divided into multiple virtual environments, enabling providers to serve many customers using shared underlying hardware.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:17:19') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('f44bc1d1-e0bb-481d-8d87-46dd1dae7413', '78e64802-4be8-4e3e-a580-164b83ca38e7', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"Azure virtual networks deployed to the same Azure region are connected by default.","options":["Yes","No"]},{"id":"stmt_2","statement":"Each Azure virtual network in a single resource group must have a unique name.","options":["Yes","No"]},{"id":"stmt_3","statement":"The Azure virtual network''s address space must be unique within a subscription.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"Yes","stmt_3":"Yes"},"answer_explanation":"Box 1: No - You would need to set up the VNET connections, for example with peering. You can connect virtual networks to each other with virtual network peering. These virtual networks can be in the same region or different regions, also known as Global VNet peering. Once virtual networks are peered, resources in both virtual networks can communicate with each other.\n\nBox 2: Yes - All Azure resource types have a scope that defines the level at which resource names must be unique. A resource must have a unique name within its scope. For example, a virtual network has a resource group scope, which means that there can be only one network named vnet-prod-westus-001 in a given resource group.\n\nBox 3: Yes - As you build your network in Azure, it is important to keep in mind the following universal design principles: Ensure non-overlapping address spaces. Make sure your VNet address space (CIDR block) does not overlap with your organization''s other network ranges.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:18:05') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('df17529d-d67b-4580-8d85-7a82571e9720', 'd16dd324-412e-44e5-bdfb-ca4edaf1d1f3', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"An Azure subscription can be associated to multiple Azure Active Directory (Azure AD) tenants.","options":["Yes","No"]},{"id":"stmt_2","statement":"You can change the Azure Active Directory (Azure AD) tenant to which an Azure subscription is associated.","options":["Yes","No"]},{"id":"stmt_3","statement":"When an Azure subscription expires, the associated Azure Active Directory (Azure AD) tenant is deleted automatically.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"Yes","stmt_3":"No"},"answer_explanation":"Statement 1: No - An Azure subscription is associated with a single Azure Active Directory (Azure AD) tenant at a time.\n\nStatement 2: Yes - You can change the Azure Active Directory (Azure AD) tenant to which an Azure subscription is associated.\n\nStatement 3: No - The Azure Active Directory (Azure AD) tenant is not automatically deleted when an associated Azure subscription expires.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:18:49') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('b71b741a-db6f-4e38-84d4-f9dd434e095f', '03f660dd-ef66-4cc2-9aff-bbc1b00335de', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"Each Azure subscription can contain multiple account administrators.","options":["Yes","No"]},{"id":"stmt_2","statement":"Each Azure subscription can be managed by using a Microsoft account only.","options":["Yes","No"]},{"id":"stmt_3","statement":"An Azure resource group contains multiple Azure subscriptions.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"No","stmt_2":"No","stmt_3":"No"},"answer_explanation":"Box 1: No - You can assign service administrators and co-administrators in the Azure portal, but there can only be one account administrator.\n\nBox 2: No - You need an Azure Active Directory account to manage a subscription, not a Microsoft account only. An account is created in Azure Active Directory when you create the subscription. Further accounts can be created in Azure Active Directory to manage the subscription.\n\nBox 3: No - Resource groups are logical containers for Azure resources. However, resource groups do not contain subscriptions. Subscriptions contain resource groups.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:19:41') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('fd6dacfd-344a-4253-8288-4d9789fd80ad', '984a6b51-6122-413f-a577-96c670345e22', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"Data that is stored in an Azure Storage account automatically has at least three copies.","options":["Yes","No"]},{"id":"stmt_2","statement":"All data that is copied to an Azure Storage account is backed up automatically to another Azure data center.","options":["Yes","No"]},{"id":"stmt_3","statement":"An Azure Storage account can contain up to 2 TB of data and up to one million files.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"Yes","stmt_2":"No","stmt_3":"No"},"answer_explanation":"Box 1: Yes - There are different replication options available with a storage account. The minimum replication option is Locally Redundant Storage (LRS). With LRS, data is replicated synchronously three times within the primary region.\n\nBox 2: No - Data is not backed up automatically to another Azure data center in every storage configuration. This depends on the replication option configured for the storage account. Locally Redundant Storage (LRS) maintains three copies of the data locally, while geo-redundant storage options replicate data to a secondary region.\n\nBox 3: No - The limits are much higher than 2 TB of data and one million files. Therefore, the statement is incorrect.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:20:42') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('495702da-9ff7-4f02-bb2f-22d9ff6574db', 'cc4d3933-1936-400a-94a4-0c949c2221a9', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"You can add an Azure Resource Manager template to an Azure blueprint.","options":["Yes","No"]},{"id":"stmt_2","statement":"You can assign an Azure blueprint to a resource group.","options":["Yes","No"]},{"id":"stmt_3","statement":"You can use Azure Blueprints to grant permissions to a resource.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"Yes","stmt_2":"No","stmt_3":"Yes"},"answer_explanation":"Box 1: Yes - Each blueprint can consist of zero or more ARM template artifacts. Azure Resource Manager templates can therefore be included in an Azure blueprint.\n\nBox 2: No - To create a new resource group for use by other artifacts within the blueprint, a resource group artifact can be added. Blueprints can be saved to a management group or subscription. A blueprint can then be assigned to a child subscription of that management group. Each published version of a blueprint can be assigned, with a maximum length of 90 characters, to an existing management group or subscription.\n\nBox 3: Yes - The blueprint definition permissions must be granted or inherited on the management group or subscription scope where it is saved. This enables permissions to be applied to resources.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:22:28') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('c116ba60-9da2-4a9b-99b8-9a35264b2dfb', 'b254c757-533f-4af5-8530-20b6fb370b78', 1, '{"question_type":"hotspot","question_text":"For each of the following statements, select Yes if the statement is true. Otherwise, select No.","question_description":"NOTE: Each correct selection is worth one point.\nHot Area:\nAnswer Area","answer_options":[{"id":"stmt_1","statement":"You can deploy Azure Resource Manager (ARM) templates by using the Azure portal.","options":["Yes","No"]},{"id":"stmt_2","statement":"Azure Resource Manager (ARM) templates can define infrastructure by using code.","options":["Yes","No"]},{"id":"stmt_3","statement":"Each Azure resource to be deployed requires a separate Azure Resource Manager (ARM) template.","options":["Yes","No"]}],"correct_answer":{"stmt_1":"Yes","stmt_2":"Yes","stmt_3":"No"},"answer_explanation":"Box 1: Yes - You can deploy Azure Resource Manager (ARM) templates by using the Azure portal.\n\nBox 2: Yes - Azure Resource Manager (ARM) templates can define infrastructure by using code.\n\nBox 3: No - It is not necessary to use a separate template for each resource. For example, an ARM template can define a virtual machine, a storage account, and a virtual network together in a single template.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:23:50') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('9ae90bff-049f-48c8-9f45-a515fff44721', 'e7af9fa7-28bb-4371-906e-14e767cd57ff', 1, '{"question_type":"matching","question_text":"Match the Azure storage services to the appropriate descriptions.","question_description":"To answer, drag the appropriate storage service from the column on the left to its description on the right. Each service may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Storage service","target_title":"Answer Area","sources":[{"id":"src_blob","text":"Azure Blob storage"},{"id":"src_disk","text":"Azure Disk storage"},{"id":"src_files","text":"Azure Files"},{"id":"src_queue","text":"Azure Queue Storage"}],"targets":[{"id":"tgt_msg","text":"Used for reliable messaging between applications"},{"id":"tgt_share","text":"Can be accessed as a network share from a Windows device"},{"id":"tgt_archive","text":"Can be configured to use the Archive access tier"}]},"correct_answer":{"tgt_msg":"src_queue","tgt_share":"src_files","tgt_archive":"src_blob"},"answer_explanation":"Azure Queue Storage is designed for asynchronous, reliable message queues between application components. Azure Files provides serverless SMB/NFS file shares mounted directly on Windows, macOS, or Linux. Azure Blob storage supports the Archive access tier for low-cost offline data storage. Azure Disk storage is persistent block storage attached to virtual machines.","points":3,"tags":["Matching","Drag-and-Drop","Storage","Azure Blob","Azure Files"]}', 'Initial version', 'usr_admin_001', '2026-10-28 19:42:01') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('4a290bd6-9dd8-462a-99d0-963170c70037', 'fe8209a7-73bc-44cb-8f98-437a656138f0', 1, '{"question_type":"matching","question_text":"Match the cloud computing benefits to the appropriate requirements.","question_description":"To answer, drag the appropriate benefit from the column on the left to its requirement on the right. Each benefit may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Benefits","target_title":"Answer Area","sources":[{"id":"src_agility","text":"Agility"},{"id":"src_elasticity","text":"Elasticity"},{"id":"src_disaster_recovery","text":"Disaster recovery"}],"targets":[{"id":"tgt_scale","text":"The ability to dynamically scale the resources available to a cloud app"},{"id":"tgt_restore","text":"The ability to use cloud-based backup services to restore resources in the event of an outage"},{"id":"tgt_deploy","text":"The ability to quickly deploy and configure cloud-based resources as app requirements change"}]},"correct_answer":{"tgt_scale":"src_elasticity","tgt_restore":"src_disaster_recovery","tgt_deploy":"src_agility"},"answer_explanation":"Elasticity matches the ability to dynamically scale the resources available to a cloud app. Elasticity is the ability of a system to automatically commission and decommission resources such as RAM, CPU, or virtual machines to match current demand closely.\n\nDisaster recovery matches the ability to use cloud-based backup services to restore resources in the event of an outage.\n\nAgility matches the ability to quickly deploy and configure cloud-based resources as application requirements change.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:48:17') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('b832af48-f447-429e-a253-5854166da5c2', '50e22285-b75e-4f4c-b2c7-e83d074ea3a0', 1, '{"question_type":"matching","question_text":"Match the terms to the correct definition.","question_description":"Instructions: To answer, drag the appropriate term from the column on the left to its description on the right. Each term may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Answer Options","target_title":"Answer Area","sources":[{"id":"src_azure_government","text":"Azure Government"},{"id":"src_gdpr","text":"GDPR"},{"id":"src_iso","text":"ISO"},{"id":"src_nist","text":"NIST"}],"targets":[{"id":"tgt_international_standards","text":"An organization that defines international standards across all industries."},{"id":"tgt_us_standards","text":"An organization that defines standards used by the United States government."},{"id":"tgt_european_privacy","text":"A European policy that regulates data privacy and data protection."},{"id":"tgt_us_government_cloud","text":"A dedicated public cloud for federal and state agencies in the United States."}]},"correct_answer":{"tgt_international_standards":"src_iso","tgt_us_standards":"src_nist","tgt_european_privacy":"src_gdpr","tgt_us_government_cloud":"src_azure_government"},"answer_explanation":"Box 1: ISO - ISO is the International Organization for Standardization. It defines international standards across industries.\n\nBox 2: NIST - NIST is the National Institute of Standards and Technology and defines standards used by the United States government.\n\nBox 3: GDPR - GDPR stands for General Data Protection Regulation and regulates data privacy and data protection in Europe.\n\nBox 4: Azure Government - Azure Government is a dedicated cloud environment designed for United States government organizations.","points":4,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:49:38') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('b2e92f69-f072-4bd8-b2f7-7be4385358da', '0dad98ac-4d54-4f6d-82e5-b371a38725c9', 1, '{"question_type":"matching","question_text":"Match the Azure service to the correct definition.","question_description":"Instructions: To answer, drag the appropriate Azure service from the column on the left to its description on the right. Each service may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Azure Options","target_title":"Answer Area","sources":[{"id":"src_advisor","text":"Azure Advisor"},{"id":"src_cognitive_services","text":"Azure Cognitive Services"},{"id":"src_app_insights","text":"Azure Application Insights"},{"id":"src_devops","text":"Azure DevOps"}],"targets":[{"id":"tgt_development","text":"An integrated solution for the deployment of code"},{"id":"tgt_recommendations","text":"A tool that provides guidance and recommendations to improve an Azure environment"},{"id":"tgt_ai","text":"A simplified tool to build intelligent Artificial Intelligence (AI) applications"},{"id":"tgt_monitor","text":"Monitors web applications"}]},"correct_answer":{"tgt_development":"src_devops","tgt_recommendations":"src_advisor","tgt_ai":"src_cognitive_services","tgt_monitor":"src_app_insights"},"answer_explanation":"Box 1: Azure DevOps - Azure DevOps is Microsoft''s primary software development and deployment platform. Azure DevOps influences the application lifecycle throughout its plan, develop, deliver, and operate phases.\n\nBox 2: Azure Advisor - Azure Advisor is a personalized cloud consultant that helps you follow best practices to optimize your Azure deployments. It analyzes resource configuration and usage telemetry and then recommends solutions that can help improve cost effectiveness, performance, high availability, and security of your Azure resources.\n\nBox 3: Azure Cognitive Services - Azure Cognitive Services provides APIs, SDKs, and services designed to help developers build intelligent applications without requiring direct AI or data science skills or knowledge.\n\nBox 4: Azure Application Insights - Azure Application Insights detects and diagnoses anomalies in web applications.","points":4,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:50:46') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('3bdf2cde-9185-48f7-adef-c791f108dab0', '721d5d02-d8fb-489c-853d-32c1db770a1a', 1, '{"question_type":"matching","question_text":"Match the cloud service models to the appropriate offerings.","question_description":"To answer, drag the appropriate model from the column on the left to its offering on the right. Each model may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Models","target_title":"Answer Area","sources":[{"id":"src_iaas","text":"Infrastructure as a service (IaaS)"},{"id":"src_paas","text":"Platform as a service (PaaS)"},{"id":"src_saas","text":"Software as a service (SaaS)"}],"targets":[{"id":"tgt_app_service","text":"Azure App Service"},{"id":"tgt_virtual_machines","text":"Azure virtual machines"},{"id":"tgt_dynamics_365","text":"Microsoft Dynamics 365"}]},"correct_answer":{"tgt_app_service":"src_paas","tgt_virtual_machines":"src_iaas","tgt_dynamics_365":"src_saas"},"answer_explanation":"Box 1: Platform as a service (PaaS) - Azure App Service is a fully managed platform for building web applications. Platform as a service provides a complete development and deployment environment in the cloud with resources that enable you to deliver applications.\n\nBox 2: Infrastructure as a service (IaaS) - Azure virtual machines are an Infrastructure as a Service offering in Azure.\n\nBox 3: Software as a service (SaaS) - Microsoft Dynamics 365 is a set of interconnected, modular Software as a Service applications and services.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:51:41') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('bfb523fd-9a4e-4757-becb-bcfe01f7b146', '1f864a7d-6ea9-489d-ad13-d2b560433aad', 1, '{"question_type":"matching","question_text":"Match the Azure service to the correct description.","question_description":"Instructions: To answer, drag the appropriate Azure service from the column on the left to its description on the right. Each service may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Services","target_title":"Answer Area","sources":[{"id":"src_sphere","text":"Azure Sphere"},{"id":"src_iot_central","text":"IoT Central"},{"id":"src_iot_hub","text":"IoT Hub"}],"targets":[{"id":"tgt_bidirectional","text":"A managed service that provides bidirectional communication between IoT devices and Azure"},{"id":"tgt_saas","text":"A fully managed software as a service (SaaS) solution to connect, monitor, and manage IoT devices at scale"},{"id":"tgt_security","text":"A software and hardware solution that provides communication and security features for IoT devices"}]},"correct_answer":{"tgt_bidirectional":"src_iot_hub","tgt_saas":"src_iot_central","tgt_security":"src_sphere"},"answer_explanation":"Box 1: IoT Hub - IoT Hub is a managed service that provides bidirectional communication between IoT devices and Azure. It acts as a central message hub for secure bidirectional communication between IoT applications and the devices they manage.\n\nBox 2: IoT Central - IoT Central is a fully managed software as a service (SaaS) solution used to connect, monitor, and manage IoT devices at scale.\n\nBox 3: Azure Sphere - Azure Sphere is a software and hardware solution that provides communication and security features for IoT devices.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:52:51') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('7376605b-d8eb-42be-801c-a19a771ca1cd', '14b0131b-0159-4a1a-9a47-92cab15a0635', 1, '{"question_type":"matching","question_text":"Match the Azure service benefits to the correct descriptions.","question_description":"Instructions: To answer, drag the appropriate benefit from the column on the left to its description on the right. Each benefit may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Answer Options","target_title":"Answer Area","sources":[{"id":"src_disaster_recovery","text":"Disaster recovery"},{"id":"src_fault_tolerance","text":"Fault tolerance"},{"id":"src_low_latency","text":"Low latency"},{"id":"src_dynamic_scalability","text":"Dynamic scalability"}],"targets":[{"id":"tgt_available_failure","text":"A cloud service that remains available after a failure occurs"},{"id":"tgt_recovered_failure","text":"A cloud service that can be recovered after a failure occurs"},{"id":"tgt_demand","text":"A cloud service that performs quickly when demand increases"},{"id":"tgt_internet","text":"A cloud service that can be accessed quickly from the Internet"}]},"correct_answer":{"tgt_available_failure":"src_fault_tolerance","tgt_recovered_failure":"src_disaster_recovery","tgt_demand":"src_dynamic_scalability","tgt_internet":"src_low_latency"},"answer_explanation":"Box 1: Fault tolerance - Fault tolerance is the ability of a service to remain available after a failure of one of the components of the service. For example, a service running on multiple servers can withstand the failure of one of the servers.\n\nBox 2: Disaster recovery - Disaster recovery is the recovery of a service after a failure. For example, restoring a virtual machine from backup after a virtual machine failure.\n\nBox 3: Dynamic scalability - Dynamic scalability is the ability for compute resources to be added to a service when the service is under heavy load. For example, in a virtual machine scale set, additional instances of the virtual machine are added when the existing virtual machines are under heavy load.\n\nBox 4: Low latency - Latency is the time a service takes to respond to requests. For example, the time it takes for a web page to be returned from a web server. Low latency means a quicker response.","points":4,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:56:44') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('baa935d0-9ff2-4556-8f7e-c77d9bd6881b', '3ee881d1-b0bf-4951-9c9b-615d1eaa89f4', 1, '{"question_type":"matching","question_text":"Match the cloud model to the correct advantage.","question_description":"Instructions: To answer, drag the appropriate cloud model from the column on the left to its advantage on the right. Each cloud model may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Cloud model","target_title":"Work Area","sources":[{"id":"src_hybrid_cloud","text":"Hybrid Cloud"},{"id":"src_private_cloud","text":"Private Cloud"},{"id":"src_public_cloud","text":"Public Cloud"}],"targets":[{"id":"tgt_no_capex","text":"No required capital expenditure."},{"id":"tgt_security_control","text":"Provides complete control over security."},{"id":"tgt_choice","text":"Provides a choice to use on-premises or cloud-based resources."}]},"correct_answer":{"tgt_no_capex":"src_public_cloud","tgt_security_control":"src_private_cloud","tgt_choice":"src_hybrid_cloud"},"answer_explanation":"Box 1: Public Cloud - With a public cloud, there is no required capital expenditure on server hardware. You pay for the cloud resources that you use as you use them.\n\nBox 2: Private Cloud - A private cloud can exist on-premises, providing the organization with control over its security.\n\nBox 3: Hybrid Cloud - A hybrid cloud combines public cloud resources and on-premises resources. Therefore, an organization has the choice to use on-premises or cloud-based resources.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:58:05') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('fc8ead25-3ba7-4b1b-b85b-ce85e668d7df', 'a943f06a-3ed3-43c0-ad4b-4bcda82ed550', 1, '{"question_type":"matching","question_text":"Match the cloud computing benefits to the correct descriptions.","question_description":"To answer, drag the appropriate benefit from the column on the left to its description on the right. Each benefit may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Benefits","target_title":"Answer Area","sources":[{"id":"src_agility","text":"Agility"},{"id":"src_geo_distribution","text":"Geo-distribution"},{"id":"src_scalability","text":"Scalability"}],"targets":[{"id":"tgt_dynamic_resources","text":"Resources can be provisioned dynamically to meet changing demands."},{"id":"tgt_multiple_regions","text":"Applications and data can be deployed to multiple regions."},{"id":"tgt_rapid_development","text":"Applications can be developed, tested, and launched rapidly."}]},"correct_answer":{"tgt_dynamic_resources":"src_scalability","tgt_multiple_regions":"src_geo_distribution","tgt_rapid_development":"src_agility"},"answer_explanation":"Box 1: Scalability - Resources can be provisioned dynamically to meet changing demands. Scalability refers to a system''s capacity to handle growing or shrinking workloads by adjusting its resource footprint. This can happen horizontally by adding or removing instances, or vertically by upgrading or downgrading the resources of an existing instance.\n\nBox 2: Geo-distribution - Applications and data can be deployed to multiple regions. Geo-distribution involves running application instances and replicating data stores across distinct physical datacenter locations globally. This can improve regional redundancy and reduce network latency for geographically distributed users.\n\nBox 3: Agility - Applications can be developed, tested, and launched rapidly. Agility describes the operational speed and flexibility provided by cloud computing. Cloud resources can be provisioned quickly, allowing organizations to develop, test, deploy, and update applications rapidly.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 19:59:13') ON CONFLICT ("id") DO NOTHING;
INSERT INTO "question_versions" ("id", "question_id", "version", "question_data", "change_reason", "changed_by", "created_at") VALUES ('685c57d7-8a67-4b2e-9e9d-a4d45c860484', '9ab52b2f-22ce-4fce-a8bc-2704cd462df7', 1, '{"question_type":"matching","question_text":"Match the cloud computing benefits to the appropriate descriptions.","question_description":"To answer, drag the appropriate benefit from the column on the left to its description on the right. Each benefit may be used once, more than once, or not at all.\n\nNOTE: Each correct match is worth one point.","answer_options":{"source_title":"Benefits","target_title":"Answer Area","sources":[{"id":"src_disaster_recovery","text":"Disaster recovery"},{"id":"src_geo_distribution","text":"Geo-distribution"},{"id":"src_high_availability","text":"High availability"},{"id":"src_scalability","text":"Scalability"}],"targets":[{"id":"tgt_compute_capacity","text":"Increase the compute capacity of apps in the cloud."},{"id":"tgt_continuous_experience","text":"Provide a continuous user experience with no apparent downtime."},{"id":"tgt_global_experience","text":"Ensure that users always have the best experience by deploying apps to all the regions where there are users."}]},"correct_answer":{"tgt_compute_capacity":"src_scalability","tgt_continuous_experience":"src_high_availability","tgt_global_experience":"src_geo_distribution"},"answer_explanation":"Box 1: Scalability - Increase the compute capacity of apps in the cloud.\n\nBox 2: High availability - Provide a continuous user experience with no apparent downtime.\n\nBox 3: Geo-distribution - Ensures that users always have the best experience by deploying apps to all the regions where there are users.\n\nDisaster recovery is not used and is the distractor in this question.","points":3,"tags":[]}', 'Imported from template', 'usr_admin_001', '2026-10-28 20:00:25') ON CONFLICT ("id") DO NOTHING;
